const path = require("node:path");
const { lstat, realpath, mkdir, open, readFile, link, unlink } = require("node:fs/promises");
const { randomUUID, createHash } = require("node:crypto");

(async () => {
  let candidate = "";
  for await (const chunk of process.stdin) candidate += chunk;

  const root = "/private/tmp/analyze-project-need-contract-v3.ZIADZg/learning";
  const source = path.join(root, "bin/csl-agent-kit.js");
  const testSource = path.join(root, "tests/cli-install-output.test.js");
  const namespace = path.join(root, "docs/analysis/components/file");
  const target = path.join(namespace, "bin/csl-agent-kit.js.md");
  const expectedHashes = new Map([
    [source, "f3a3342b514d0c67381672229a20afffbc31a1448332addeb9696948a6bdc7b5"],
    [testSource, "ce35af5d92de14a0448209f8a0472a5ad3f7f5a8ff16dea8200a2c00466c6897"],
  ]);

  if (await realpath(root) !== root) throw new Error("Git root canonical path changed.");
  const sourceStat = await lstat(source);
  if (!sourceStat.isFile() || sourceStat.isSymbolicLink()) throw new Error("Source target is not a regular file.");
  const sourceReal = await realpath(source);
  const sourceRelative = path.relative(root, sourceReal);
  if (sourceRelative.startsWith(`..${path.sep}`) || sourceRelative === ".." || path.isAbsolute(sourceRelative)) throw new Error("Source target escapes Git root.");
  const outputRelative = path.relative(namespace, target);
  if (!outputRelative || outputRelative.startsWith(`..${path.sep}`) || outputRelative === ".." || path.isAbsolute(outputRelative)) throw new Error("Output target escapes namespace.");

  for (const [file, expected] of expectedHashes) {
    const actual = createHash("sha256").update(await readFile(file)).digest("hex");
    if (actual !== expected) throw new Error(`Analyzed source changed: ${path.relative(root, file)}`);
  }

  const parent = path.dirname(target);
  const chain = [
    root,
    path.join(root, "docs"),
    path.join(root, "docs/analysis"),
    path.join(root, "docs/analysis/components"),
    path.join(root, "docs/analysis/components/file"),
    parent,
  ];
  const identities = new Map();

  for (const segment of chain) {
    let stat;
    try {
      stat = await lstat(segment);
    } catch (error) {
      if (error.code !== "ENOENT") throw error;
      await mkdir(segment);
      stat = await lstat(segment);
    }
    if (stat.isSymbolicLink() || !stat.isDirectory()) throw new Error(`Unsafe output parent: ${segment}`);
    identities.set(segment, { dev: stat.dev, ino: stat.ino });
  }

  async function recheckParents() {
    for (const segment of chain) {
      const stat = await lstat(segment);
      const identity = identities.get(segment);
      if (stat.isSymbolicLink() || !stat.isDirectory() || stat.dev !== identity.dev || stat.ino !== identity.ino) {
        throw new Error(`Output parent changed: ${segment}`);
      }
    }
  }

  async function requireAbsent() {
    try {
      const stat = await lstat(target);
      if (!stat.isFile() || stat.isSymbolicLink()) throw new Error(`Unsafe active target: ${target}`);
      throw new Error(`Active target appeared before publication: ${target}`);
    } catch (error) {
      if (error.code === "ENOENT") return;
      throw error;
    }
  }

  await requireAbsent();
  await recheckParents();

  const temp = path.join(parent, `.${path.basename(target)}.${process.pid}.${randomUUID()}.tmp`);
  let owned = false;
  try {
    const handle = await open(temp, "wx");
    owned = true;
    try {
      await handle.writeFile(candidate, "utf8");
    } finally {
      await handle.close();
    }

    await recheckParents();
    await requireAbsent();
    await link(temp, target);
    await unlink(temp);
  } finally {
    if (owned) {
      try {
        await unlink(temp);
      } catch (error) {
        if (error.code !== "ENOENT") throw error;
      }
    }
  }
})().catch((error) => {
  console.error(error.message);
  process.exitCode = 1;
});
